// Build a strict-JSON LLM prompt covering all three channels in one call.
const body = $('Webhook').first().json.body || $('Webhook').first().json;
const listing = $input.first().json;

if (!listing) throw new Error(`Listing ${body.listing_id} not found`);

const allowed = ['pinterest', 'x', 'instagram'];
const requested = Array.isArray(body.channels) && body.channels.length
  ? body.channels.filter(c => allowed.includes(c))
  : allowed;
if (!requested.length) throw new Error('No valid channels requested');

const generateVisual = body.generate_visual === true || body.generate_visual === 'true';
const scheduleAt = body.schedule_at || null;

const system = `You are a social media copywriter. Output ONLY valid minified JSON.
Schema (omit channels NOT in this list: ${requested.join(', ')}):
{
  "pinterest": {"title": string<=100, "description": string<=500, "hashtags": string[5..10]},
  "x":         {"post":  string<=280},
  "instagram": {"caption": string<=2200, "hashtags": string[10..30]}
}
Rules:
- Pinterest copy is descriptive and aspirational (vertical-pin context).
- X copy fits 280 chars including hashtags; punchy, 1-3 hashtags.
- Instagram caption is friendly with light emoji; hashtags sit after the caption.
- Never invent prices or discounts. Always keyword-rich for the niche.`;

const tagsCsv = Array.isArray(listing.tags) ? listing.tags.join(', ') : '';
const user = `Listing title: ${listing.title}\nNiche: ${listing.niche || ''}\nKind: ${listing.kind}\nPrice: $${listing.price}\nTop tags: ${tagsCsv}\nDescription: ${listing.description}`;

return [{ json: {
  listing_id: listing.listing_id,
  channels: requested,
  generate_visual: generateVisual,
  schedule_at: scheduleAt,
  prompt: `${system}\n\n${user}`
} }];

// Parse + validate + optionally call workflow 02 for a shared visual.
const ollama = $input.first().json;
const input = $('Build Prompt').first().json;

let parsed;
try {
  parsed = typeof ollama.response === 'string' ? JSON.parse(ollama.response) : ollama.response;
} catch (e) {
  throw new Error(`LLM returned non-JSON: ${e.message}`);
}

const channelToCopy = (channel) => {
  const c = parsed[channel];
  if (!c) throw new Error(`Missing copy for channel ${channel}`);
  if (channel === 'pinterest') {
    if (!c.title || c.title.length > 100) throw new Error('Pinterest title invalid');
    if (!c.description || c.description.length > 500) throw new Error('Pinterest description invalid');
    const hashtags = Array.isArray(c.hashtags) ? c.hashtags : [];
    return `${c.title}\n\n${c.description}\n\n${hashtags.map(h => h.startsWith('#') ? h : '#' + h).join(' ')}`;
  }
  if (channel === 'x') {
    if (!c.post || c.post.length > 280) throw new Error('X post invalid');
    return c.post;
  }
  if (channel === 'instagram') {
    if (!c.caption || c.caption.length > 2200) throw new Error('Instagram caption invalid');
    const hashtags = Array.isArray(c.hashtags) ? c.hashtags : [];
    return `${c.caption}\n\n${hashtags.map(h => h.startsWith('#') ? h : '#' + h).join(' ')}`;
  }
  return JSON.stringify(c);
};

let imagePath = null;
if (input.generate_visual) {
  try {
    const visual = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://localhost:5678/webhook/visual-generate',
      headers: { 'X-Webhook-Secret': process.env.N8N_WEBHOOK_SECRET },
      body: { listing_id: input.listing_id, width: 1080, height: 1080 },
      json: true,
      timeout: 360000
    });
    imagePath = visual?.mockup?.file_path || null;
  } catch (e) {
    // Soft-fail: ad copy still goes out, just without a generated visual.
    console.warn(`visual-generate failed: ${e.message}`);
  }
}

const scheduledFor = input.schedule_at
  ? new Date(input.schedule_at).toISOString()
  : new Date(Date.now() + 60 * 60 * 1000).toISOString();

// Emit one item per channel so the Postgres node inserts each row independently.
return input.channels.map(channel => ({
  json: {
    listing_id: input.listing_id,
    channel,
    copy: channelToCopy(channel),
    image_path: imagePath,
    scheduled_for: scheduledFor,
    raw: parsed[channel] || null
  }
}));
